# -*- coding: utf-8 -*-
"""
BÀI SÁP NHẬP V4.4 - XỬ LÝ CÓ KIỂM SOÁT MÃ 4017981444 / TRẦN THỊ NGỌC

Mục tiêu:
- Giữ nguyên file Excel nguồn gốc.
- Bổ sung một sổ điều chỉnh nguồn có kiểm soát, loại đúng dòng Excel 7663
  (Nghi Hải) khỏi registry dùng cho cổng sáp nhập, giữ dòng 7861 (Nghi Thuỷ).
- Căn cứ khóa an toàn: cùng mã/cùng họ tên/cùng ngày sinh; DB 2025-2026 có đúng
  một hồ sơ người này và hồ sơ năm nằm tại Tiểu học Nghi Thuỷ (mã 40413403).
- Sau sửa, phương án Nghi Thuỷ -> Nghi Tân phải PASS V4.3 + PASS V4.1 + mô phỏng ĐẠT.

Bộ cài KHÔNG thực hiện sáp nhập và KHÔNG ghi phocap.db.
"""
from __future__ import annotations

import base64
import hashlib
import json
import os
import py_compile
import shutil
import sqlite3
import subprocess
import sys
import unicodedata
from datetime import datetime
from pathlib import Path

VERSION = "V4.4"
PLAN_ID = "PA2026-D9C894490094"
STAFF_CODE = "4017981444"
STAFF_NAME = "Trần Thị Ngọc"
STAFF_DOB = "1987-01-12"
SOURCE_SCHOOL_CODE = "40413403"  # Nghi Thuỷ
DUPLICATE_SCHOOL_CODE = "40413408"  # Nghi Hải
PAST_YEAR_CODE = "2025-2026"

SERVICE_REL = "app/services/school_merger_source_audit_service.py"
CORRECTION_REL = "data/school_merger_source_corrections.json"
RAW_REGISTRY_REL = "data/school_merger_source_rosters/TH_2025_2026.json"

EXPECTED_V43_SERVICE_HASH = "e39bdd48c5666766e7b3f37076a05c3f463eebd86af3f6ae71ae003ec7829605"
PATCHED_SERVICE_HASH = "a2b6d14bb70d2c512fc8b9a2cb6bc715ac88c283411049bec97a0b357f59dc0e"
EXPECTED_RAW_REGISTRY_HASH = "26b4356ffd9098ac682b1ed74432c443022fcecbe68724336b2adbfd5f053f98"
CORRECTION_HASH = "2307bb52bda0b879ab02c3de7c69b95905cbcbcff368100c9829e2d6d6d2ebcc"

PATCHED_SERVICE_B64 = ""
CORRECTION_B64 = ""


def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        for block in iter(lambda: f.read(1024 * 1024), b""):
            h.update(block)
    return h.hexdigest()


def db_physical_state(db: Path) -> str:
    h = hashlib.sha256()
    for suffix in ("", "-wal"):
        p = Path(str(db) + suffix)
        h.update(suffix.encode("utf-8"))
        if not p.exists():
            h.update(b"MISSING")
            continue
        h.update(str(p.stat().st_size).encode("ascii"))
        h.update(sha256_file(p).encode("ascii"))
    return h.hexdigest()


def norm(value) -> str:
    text = str(value or "").strip().lower().replace("đ", "d")
    text = unicodedata.normalize("NFD", text)
    return "".join(ch for ch in text if unicodedata.category(ch) != "Mn")


def find_project_root() -> Path:
    here = Path(__file__).resolve().parent
    candidates = [here, Path.cwd(), here.parent]
    if os.name == "nt":
        candidates.append(Path(r"C:\PhoCap"))
    seen = set()
    for c in candidates:
        try:
            c = c.resolve()
        except Exception:
            continue
        if str(c) in seen:
            continue
        seen.add(str(c))
        if (c / "app").is_dir() and (c / "data" / "phocap.db").is_file():
            return c
    raise RuntimeError("Không xác định được dự án. Hãy chép file cài vào C:\\PhoCap và chạy lại từ C:\\PhoCap.")


def atomic_write(path: Path, data: bytes) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(path.name + ".v44.tmp")
    tmp.write_bytes(data)
    os.replace(tmp, path)


def audit_subprocess(root: Path) -> dict:
    code = r'''
import json
from app.services.school_merger_source_audit_service import audit_official_plan_source, source_registry_summary, audit_official_plans
from app.services.school_merger_preview_service import build_official_plan_impact_preview
pid="PA2026-D9C894490094"
a=audit_official_plan_source(pid)
p=build_official_plan_impact_preview(pid)
th=audit_official_plans(level_code="TH")
out={
 "audit": a,
 "preview": {
   "v43_source_check_ok": bool(p.get("v43_source_check_ok")),
   "v41_state_check_ok": bool(p.get("v41_state_check_ok")),
   "simulation_ok": bool(p.get("simulation_ok")),
   "safe_for_future_execution": bool(p.get("safe_for_future_execution")),
   "impact_state_fingerprint": p.get("impact_state_fingerprint"),
   "source_audit_fingerprint": (p.get("source_audit") or {}).get("fingerprint"),
   "staff_rollover_candidates": ((p.get("inventory") or {}).get("staff_rollover_candidates")),
   "blockers": p.get("blockers") or [],
 },
 "summary": source_registry_summary(),
 "th": {"total": th.get("total"), "pass": th.get("pass_count"), "block": th.get("block_count")},
}
print(json.dumps(out, ensure_ascii=True, default=str))
'''
    env = dict(os.environ)
    env["PYTHONPATH"] = str(root) + (os.pathsep + env["PYTHONPATH"] if env.get("PYTHONPATH") else "")
    env["PYTHONIOENCODING"] = "utf-8"
    env["PYTHONUTF8"] = "1"
    proc = subprocess.run(
        [sys.executable, "-c", code], cwd=str(root), env=env,
        capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=180,
    )
    if proc.returncode != 0:
        raise RuntimeError("Audit V4.4 lỗi:\n" + (proc.stderr or proc.stdout or "Không có chi tiết"))
    lines = [x for x in proc.stdout.splitlines() if x.strip()]
    if not lines:
        raise RuntimeError("Audit V4.4 không trả dữ liệu.")
    return json.loads(lines[-1])


def validate_db_evidence(db: Path) -> dict:
    uri = db.resolve().as_uri() + "?mode=ro"
    con = sqlite3.connect(uri, uri=True, timeout=30)
    con.row_factory = sqlite3.Row
    try:
        integrity = str(con.execute("PRAGMA integrity_check").fetchone()[0])
        fk = con.execute("PRAGMA foreign_key_check").fetchall()
        if integrity.lower() != "ok" or fk:
            raise RuntimeError(f"Database chưa đạt integrity/FK: integrity={integrity}, FK={len(fk)}")
        year = con.execute("SELECT id,code FROM school_years WHERE code=? LIMIT 1", (PAST_YEAR_CODE,)).fetchone()
        if year is None:
            raise RuntimeError("Không tìm thấy năm 2025-2026.")
        src = con.execute("SELECT id,code,name,commune_id,is_active FROM schools WHERE code=? LIMIT 1", (SOURCE_SCHOOL_CODE,)).fetchone()
        dup = con.execute("SELECT id,code,name,commune_id,is_active FROM schools WHERE code=? LIMIT 1", (DUPLICATE_SCHOOL_CODE,)).fetchone()
        if src is None or dup is None:
            raise RuntimeError("Không tìm đủ Nghi Thuỷ/Nghi Hải theo mã trường đã khóa.")
        members = con.execute(
            "SELECT id,ministry_staff_code,full_name,date_of_birth,is_active FROM staff_members WHERE ministry_staff_code=?",
            (STAFF_CODE,),
        ).fetchall()
        if len(members) != 1:
            raise RuntimeError(f"Mã {STAFF_CODE} trong staff_members khớp {len(members)} hồ sơ; yêu cầu đúng 1.")
        member = members[0]
        if norm(member["full_name"]) != norm(STAFF_NAME) or str(member["date_of_birth"] or "")[:10] != STAFF_DOB:
            raise RuntimeError(
                f"Nhân thân DB không khớp: {member['full_name']} / {member['date_of_birth']}; dừng."
            )
        yrs = con.execute(
            "SELECT id,school_id,status_code,is_active,source_status_label,notes FROM staff_year_records "
            "WHERE staff_member_id=? AND school_year_id=?",
            (member["id"], year["id"]),
        ).fetchall()
        if len(yrs) != 1:
            raise RuntimeError(f"Mã {STAFF_CODE} có {len(yrs)} hồ sơ năm 2025-2026; yêu cầu đúng 1.")
        yr = yrs[0]
        if int(yr["school_id"]) != int(src["id"]):
            actual = con.execute("SELECT code,name FROM schools WHERE id=?", (yr["school_id"],)).fetchone()
            raise RuntimeError(
                f"DB năm 2025-2026 không đặt {STAFF_CODE} tại Nghi Thuỷ mà ở {dict(actual) if actual else yr['school_id']}; dừng."
            )
        return {
            "integrity": integrity,
            "fk_count": len(fk),
            "year_id": int(year["id"]),
            "member": dict(member),
            "year_record": dict(yr),
            "canonical_school": dict(src),
            "duplicate_school": dict(dup),
        }
    finally:
        con.close()


def validate_raw_registry(path: Path) -> dict:
    if sha256_file(path) != EXPECTED_RAW_REGISTRY_HASH:
        raise RuntimeError(
            "Registry nguồn TH_2025_2026.json đã khác bản V4.3.1 được kiểm thử; không tự sửa chồng."
        )
    payload = json.loads(path.read_text(encoding="utf-8"))
    rows = [x for x in (payload.get("rows") or []) if str(x.get("staff_code") or "").strip() == STAFF_CODE]
    if len(rows) != 2:
        raise RuntimeError(f"Nguồn thô mã {STAFF_CODE} hiện có {len(rows)} dòng, không còn đúng mẫu 2 dòng.")
    by_row = {int(x.get("excel_row")): x for x in rows}
    if set(by_row) != {7663, 7861}:
        raise RuntimeError(f"Hai dòng nguồn của {STAFF_CODE} không còn ở 7663/7861: {sorted(by_row)}")
    a, b = by_row[7663], by_row[7861]
    for row in (a, b):
        if norm(row.get("full_name")) != norm(STAFF_NAME) or str(row.get("date_of_birth") or "") != "12/01/1987":
            raise RuntimeError("Hai dòng nguồn không còn cùng nhân thân Trần Thị Ngọc 12/01/1987.")
        if norm(row.get("status_label")) != norm("Đang làm việc"):
            raise RuntimeError("Một trong hai dòng nguồn không còn trạng thái Đang làm việc; dừng để rà soát lại.")
    if "nghi hai" not in norm(a.get("school_name")) or "nghi thuy" not in norm(b.get("school_name")):
        raise RuntimeError("Dòng 7663/7861 không còn tương ứng Nghi Hải/Nghi Thuỷ.")
    return {"rows": rows, "source_sha256": payload.get("source_sha256"), "dataset_id": payload.get("dataset_id")}


def validate_before(before: dict) -> None:
    audit = before.get("audit") or {}
    if audit.get("pass"):
        return
    checks = audit.get("school_checks") or []
    source = next((x for x in checks if x.get("role") == "SOURCE"), None)
    target = next((x for x in checks if x.get("role") == "TARGET"), None)
    if not source or not target:
        raise RuntimeError("Audit trước V4.4 không xác định đủ nguồn/đích.")
    if target.get("status") != "PASS":
        raise RuntimeError("Nghi Tân hiện không PASS nguồn; V4.4 chỉ xử lý đúng xung đột 4017981444.")
    issues = source.get("issues") or []
    keys = [(str(x.get("code")), str(x.get("staff_code") or "")) for x in issues]
    if keys != [("ACTIVE_IN_MULTIPLE_SOURCE_SCHOOLS", STAFF_CODE)]:
        raise RuntimeError(f"Nghi Thuỷ hiện có blocker khác ngoài 4017981444: {keys}")
    if int(source.get("source_active_rows") or 0) != 53 or int(source.get("active_db_eligible") or 0) != 53:
        raise RuntimeError(
            f"Nghi Thuỷ không còn mẫu 53/53 trước sửa: nguồn={source.get('source_active_rows')} DB={source.get('active_db_eligible')}"
        )


def validate_after(after: dict) -> None:
    audit = after.get("audit") or {}
    preview = after.get("preview") or {}
    summary = after.get("summary") or {}
    if not audit.get("pass"):
        raise RuntimeError("Sau V4.4, audit Nghi Thuỷ -> Nghi Tân vẫn chưa PASS: " + " | ".join(audit.get("blockers") or []))
    checks = audit.get("school_checks") or []
    target = next((x for x in checks if x.get("role") == "TARGET"), {})
    source = next((x for x in checks if x.get("role") == "SOURCE"), {})
    if target.get("status") != "PASS" or source.get("status") != "PASS":
        raise RuntimeError("Sau V4.4 chưa PASS đồng thời Nghi Tân và Nghi Thuỷ.")
    if int(source.get("source_active_rows") or 0) != 53 or int(source.get("active_db_eligible") or 0) != 53:
        raise RuntimeError("Sau V4.4 Nghi Thuỷ không còn khớp 53/53.")
    if int(target.get("source_active_rows") or 0) != 56 or int(target.get("active_db_eligible") or 0) != 56:
        raise RuntimeError("Sau V4.4 Nghi Tân không còn khớp 56/56.")
    if not all(bool(preview.get(k)) for k in ("v43_source_check_ok", "v41_state_check_ok", "simulation_ok", "safe_for_future_execution")):
        raise RuntimeError(f"Cổng xem trước sau V4.4 chưa mở đủ: {preview}")
    if int(preview.get("staff_rollover_candidates") or 0) != 109:
        raise RuntimeError(f"Mô phỏng rollover sau V4.4 không còn 109 mà là {preview.get('staff_rollover_candidates')}.")
    if int(summary.get("correction_count") or 0) < 1 or "V4.4-TH-2025-2026-4017981444-NGHI-THUY" not in (summary.get("correction_ids") or []):
        raise RuntimeError("Sổ điều chỉnh V4.4 chưa được engine ghi nhận.")


def main() -> None:
    root = find_project_root()
    db = root / "data" / "phocap.db"
    service = root / SERVICE_REL
    correction = root / CORRECTION_REL
    raw_registry = root / RAW_REGISTRY_REL

    print("=" * 100)
    print("BÀI SÁP NHẬP V4.4 - XỬ LÝ MÃ 4017981444 / TRẦN THỊ NGỌC")
    print("Dự án:", root)
    print("Database:", db)
    print("Nguyên tắc: KHÔNG sửa Excel gốc; KHÔNG ghi phocap.db; chỉ thêm điều chỉnh nguồn có kiểm soát.")
    print("=" * 100)

    db_before = db_physical_state(db)
    evidence = validate_db_evidence(db)
    raw_info = validate_raw_registry(raw_registry)

    current_service_hash = sha256_file(service) if service.exists() else ""
    current_correction_hash = sha256_file(correction) if correction.exists() else ""
    already = current_service_hash == PATCHED_SERVICE_HASH and current_correction_hash == CORRECTION_HASH
    if current_service_hash not in {EXPECTED_V43_SERVICE_HASH, PATCHED_SERVICE_HASH}:
        raise RuntimeError(
            f"{SERVICE_REL} không đúng V4.3.1/V4.4 đã kiểm thử. Hash hiện tại: {current_service_hash}"
        )
    if correction.exists() and current_correction_hash != CORRECTION_HASH:
        raise RuntimeError(
            f"{CORRECTION_REL} đã tồn tại với nội dung khác. Không ghi đè sổ điều chỉnh thủ công. Hash={current_correction_hash}"
        )

    before = audit_subprocess(root)
    if not already:
        validate_before(before)

    stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    backup_dir = root / "backups" / f"backup_truoc_bai_sap_nhap_v4_4_{stamp}"
    backup_dir.mkdir(parents=True, exist_ok=True)
    service_backup = backup_dir / SERVICE_REL
    service_backup.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(service, service_backup)
    correction_existed = correction.exists()
    if correction_existed:
        corr_backup = backup_dir / CORRECTION_REL
        corr_backup.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(correction, corr_backup)

    try:
        if not already:
            svc_data = base64.b64decode(PATCHED_SERVICE_B64)
            corr_data = base64.b64decode(CORRECTION_B64)
            if sha256_bytes(svc_data) != PATCHED_SERVICE_HASH or sha256_bytes(corr_data) != CORRECTION_HASH:
                raise RuntimeError("Payload V4.4 sai hash nội bộ.")
            atomic_write(service, svc_data)
            py_compile.compile(str(service), doraise=True)
            atomic_write(correction, corr_data)

        after = audit_subprocess(root)
        validate_after(after)
        db_after = db_physical_state(db)
        if db_after != db_before:
            raise RuntimeError("Dấu vân tay vật lý phocap.db/WAL đã thay đổi dù V4.4 không được ghi DB.")

        out_dir = root / "exports" / "Bai_Sap_Nhap_V4_4_Xu_Ly_4017981444"
        out_dir.mkdir(parents=True, exist_ok=True)
        report = out_dir / f"bao_cao_v4_4_{stamp}.json"
        report.write_text(json.dumps({
            "version": VERSION,
            "plan_id": PLAN_ID,
            "staff_code": STAFF_CODE,
            "staff_name": STAFF_NAME,
            "decision": "Giữ dòng nguồn Nghi Thuỷ (Excel 7861), loại dòng trùng Nghi Hải (Excel 7663) khỏi registry sáp nhập.",
            "raw_source_unchanged": True,
            "database_unchanged": True,
            "db_evidence": evidence,
            "raw_registry_evidence": raw_info,
            "before": before,
            "after": after,
            "backup_source": str(backup_dir),
            "correction_file": str(correction),
            "created_at": datetime.now().isoformat(timespec="seconds"),
        }, ensure_ascii=False, indent=2, default=str), encoding="utf-8")

        print("\n" + "=" * 100)
        print("BÀI SÁP NHẬP V4.4 - CÀI ĐẶT THÀNH CÔNG")
        print("Database: KHÔNG THAY ĐỔI")
        print("Excel nguồn gốc: KHÔNG THAY ĐỔI")
        print("Quyết định nguồn: 4017981444 - Trần Thị Ngọc -> giữ tại Nghi Thuỷ; loại dòng trùng Nghi Hải khỏi registry đối chiếu.")
        print("Nghi Tân: nguồn hoạt động/DB đủ rollover = 56/56 - PASS")
        print("Nghi Thuỷ: nguồn hoạt động/DB đủ rollover = 53/53 - PASS")
        print("Cổng V4.3: PASS | V4.1: PASS | Mô phỏng: PASS | Đủ điều kiện xem trước thực hiện: CÓ")
        print("Rollover dự kiến khi sáp nhập Nghi Thuỷ -> Nghi Tân: 109 hồ sơ")
        print(f"TH toàn tỉnh sau điều chỉnh: PASS {after.get('th',{}).get('pass')} / BLOCK {after.get('th',{}).get('block')} / tổng {after.get('th',{}).get('total')}")
        print("Backup mã nguồn trước V4.4:", backup_dir)
        print("Báo cáo:", report)
        print("KHÔNG thực hiện sáp nhập trong bộ cài này.")
        print("=" * 100)
    except Exception:
        try:
            shutil.copy2(service_backup, service)
            if correction_existed:
                shutil.copy2(backup_dir / CORRECTION_REL, correction)
            elif correction.exists():
                correction.unlink()
        except Exception:
            pass
        raise


if __name__ == "__main__":
    try:
        main()
    except Exception as exc:
        print("\n" + "=" * 100)
        print("DỪNG AN TOÀN - BÀI SÁP NHẬP V4.4")
        print("Lỗi:", exc)
        print("Nếu đã chạm file nguồn, bộ cài đã cố gắng khôi phục từ backup.")
        print("Bộ cài KHÔNG thực hiện sáp nhập và KHÔNG chủ động ghi phocap.db.")
        print("=" * 100)
        raise SystemExit(1)
